export function observationsFromRecords(records) {
  const observations = {};
  for (const record of records ?? []) {
    const workType = record?.routing?.workType ?? "default";
    for (const attempt of record?.attempts ?? []) {
      if (!attempt?.endpoint || !["completion", "refusal"].includes(attempt.outcome)) continue;
      const observation = (observations[attempt.endpoint] ??= {})[workType] ??= { attempts: 0, successes: 0, latencyMs: 0 };
      observation.attempts += 1; observation.successes += attempt.outcome === "completion" ? 1 : 0;
    }
  }
  return observations;
}
